const l=[{id:"T01",title:"Dai, Milkman & Riis · 2014 · Neuanfänge und Zielbeginn",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Drei Archivdatensätze zeigten häufigere erste Schritte zum Ziel rund um markante Kalenderdaten: Diätsuchen, Besuche im Hochschulsport und Selbstverpflichtungsverträge.",limitation:"Beobachtete Anfänge belegen weder Ursache und Wirkung noch anhaltende Veränderung. Auch der Effekt, ein beliebiges Datum zum Anfang zu erklären, wurde nicht gezeigt."},{id:"T02",title:"Dai, Milkman & Riis · 2015 · Markante Kalenderdaten und Zielbeginn",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"Von 165 online teilnehmenden Erwachsenen wählten 25,61% eine Erinnerung für den 20. März, wenn er als Frühlingsanfang beschrieben wurde. Als dritter Donnerstag waren es 7,23%.",limitation:"Verglichen wurde die Auswahl einer Erinnerung, keine tatsächliche Handlung oder dauerhafte Veränderung. Einen persönlichen Anfangstag zu erklären ist eine Anpassung von ODA."},{id:"T03",title:"Gollwitzer & Sheeran · 2006 · Wenn-dann-Pläne und Zielerreichung",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"In 94 unabhängigen Tests mit 8.461 Menschen verbesserten konkrete Wenn-dann-Pläne im Durchschnitt das Erreichen von Zielen: d = 0,65, 95%-Konfidenzintervall [0,60; 0,70].",limitation:"Unterschiedliche Situationen und ältere Methoden begrenzen die Übertragbarkeit. Der Effekt bedeutet nicht 65% mehr Erfolg. Dieser kurze ODA-Planer wurde nicht geprüft."},{id:"T04",title:"Wang, Wang & Gai · 2021 · Mentales Kontrastieren mit Wenn-dann-Plänen",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"Eine Metaanalyse von 21 Artikeln und 24 Effekten mit 15.907 Menschen fand einen bescheidenen durchschnittlichen Nutzen für das Erreichen von Zielen: g = 0,336, 95%-Konfidenzintervall [0,229; 0,443].",limitation:"Die Ergebnisse unterschieden sich; Publikationsverzerrung war möglich. Zwei große Online-Stichproben prägen die Gesamtzahl. Vorstellungen ziehen keine Ergebnisse an. ODAs Übung wurde nicht geprüft."},{id:"T05",title:"Harkin et al. · 2016 · Fortschritte bei Zielen beobachten",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"In 138 randomisierten Studien mit 19.951 Menschen verbesserten Maßnahmen zum Beobachten von Fortschritten im Durchschnitt das Erreichen von Zielen: d = 0,40, 95%-Konfidenzintervall [0,32; 0,48].",limitation:"Ziele und Methoden unterschieden sich. Schriftliches Festhalten und Berichten hingen in zusätzlichen Analysen mit größeren Effekten zusammen. Öffentliches Teilen ist nicht nötig. ODAs Aufzeichnung wurde nicht geprüft."},{id:"T06",title:"Lally et al. · 2010 · Wie Gewohnheiten entstehen: Modellschätzungen",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"Eine 84-tägige Beobachtungsstudie begleitete 96 Freiwillige. Für 39 gut passende Kurven schätzte das Modell 18 bis 254 Tage bis zu 95% des geschätzten individuellen Endniveaus der Automatisierung. Der Median war 66.",limitation:"Das waren Modellschätzungen, keine beobachteten Abschlussdaten. Selbstberichte zu alltäglichen Gesundheitsverhaltensweisen belegen weder einen allgemeinen Zeitplan noch eine Grenze bei zwei verpassten Gelegenheiten."},{id:"T07",title:"Singh et al. · 2024 · Wie lange Gewohnheiten brauchen",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"Eine Übersicht über 20 Studien zu Gesundheitsverhalten mit 2.601 Menschen fand stark unterschiedliche Zeitschätzungen. Nur vier Studien lieferten Angaben zur Dauer. Einzelne Schätzungen reichten von 4 bis 335 Tagen.",limitation:"Elf Studien hatten ein hohes Verzerrungsrisiko. Die Zeitdefinitionen unterschieden sich. Vorher-nachher-Veränderungen der Gewohnheitsstärke sind weder ein kontrollierter Behandlungseffekt noch deine persönliche Frist."},{id:"T08",title:"Wood & Rünger · 2016 · Psychologie der Gewohnheit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Die Übersicht beschreibt, wie wiederholte Handlungen in wiederkehrenden Situationen zunehmend durch Startsignale ausgelöst werden können. Bewusste Ziele und Gewohnheiten können zusammenwirken.",limitation:"Zusammenfassende theoretische Übersicht, keine neue Studie oder zusammengefasste Effektgröße. Sie zeigt nicht, dass der Platz eines Gegenstands Motivation unnötig macht oder jedes komplexe Ziel automatisch wird."},{id:"T09",title:"Bandura · 1977 · Theorie der Selbstwirksamkeit",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Banduras Theorie nennt eigene Erfolge, das Beobachten anderer, Ermutigung und körperliche Zustände als Quellen der Erwartung, eine bestimmte Handlung ausführen zu können. Eigene Bewältigungserfahrungen erhalten besonderes Gewicht.",limitation:"Die Theorie verbindet frühere Forschung und ist keine neue Studie. Sie beweist nicht, dass jeder kleine Schritt Selbstvertrauen steigert oder umfassendes Können belegt."},{id:"T11",title:"Scullin et al. · 2018 · Aufgabenlisten vor dem Schlafen",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"In einer Labornacht schrieben 57 gesunde Erwachsene von 18 bis 30 Jahren fünf Minuten auf Papier über künftige Aufgaben oder abgeschlossene Tätigkeiten. Die mittlere Einschlafzeit betrug 15,82 beziehungsweise 25,09 Minuten.",limitation:"Verglichen wurde mit einer anderen Schreibaufgabe. Signifikant mehr Gesamtschlaf oder langfristiger Nutzen bei Schlaflosigkeit wurde nicht belegt. Gesprochene Suggestionen und ODAs kurzer Rückblick wurden nicht geprüft."},{id:"T12",title:"Wohl, Pychyl & Bennett · 2010 · Selbstvergebung und Aufschieben vor Prüfungen",url:"https://doi.org/10.1016/j.paid.2010.01.029",type:"research",finding:"Bei 119 Studierenden im ersten Jahr hing mehr Selbstvergebung für das Aufschieben vor einer Zwischenprüfung mit weniger Aufschieben vor der nächsten zusammen.",limitation:"Beobachtungen in einem Kurs belegen keine Ursache und Wirkung. Der Abstract bestätigt weder einen Effektkoeffizienten noch den Nutzen eines vorgegebenen Satzes."},{id:"T15",title:"Oettingen et al. · 2015 · Mentales Kontrastieren und Zeitmanagement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Studie 1 teilte 84 deutsche Studierende zufällig Gruppen zu. Die kombinierte Übungsgruppe plante mehr Stunden als zwei Kontrollgruppen. Der geplante Vergleich war signifikant; der Gesamttest lag bei p = 0,057.",limitation:"Geplante Stunden maßen Absichten, keine geleisteten Stunden oder fertigen Projekte. Die Studie bestätigt nicht ODAs kurzen Schritt mit Rückblick am nächsten Tag."},{id:"T17",title:"James Clear · Die Zwei-Minuten-Regel",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"Clear schlägt vor, eine neue Handlung auf einen kurzen Einstieg zu verkleinern. Das ist ein Praxistipp für einen zugänglichen Anfang.",limitation:"Kontrollierte Forschung belegt nicht, dass genau zwei Minuten optimal sind. Vorbereitung ist etwas anderes, als einen hilfreichen Teil der eigentlichen Handlung abzuschließen."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · Theorie der Selbstwirksamkeit",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Banduras Theorie nennt eigene Erfolge, das Beobachten anderer, Ermutigung und körperliche Zustände als Quellen der Erwartung, eine bestimmte Handlung ausführen zu können. Eigene Bewältigungserfahrungen erhalten besonderes Gewicht.",limitation:"Die Theorie verbindet frühere Forschung und ist keine neue Studie. Sie beweist nicht, dass jeder kleine Schritt Selbstvertrauen steigert oder umfassendes Können belegt."},{id:"habits",title:"Lally et al. · 2010 · Wie Gewohnheiten entstehen: Modellschätzungen",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"Eine 84-tägige Beobachtungsstudie begleitete 96 Freiwillige. Für 39 gut passende Kurven schätzte das Modell 18 bis 254 Tage bis zu 95% des geschätzten individuellen Endniveaus der Automatisierung. Der Median war 66.",limitation:"Das waren Modellschätzungen, keine beobachteten Abschlussdaten. Selbstberichte zu alltäglichen Gesundheitsverhaltensweisen belegen weder einen allgemeinen Zeitplan noch eine Grenze bei zwei verpassten Gelegenheiten."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP",url:"https://woopmylife.org/en/home",type:"technique",finding:"WOOP verbindet Wunsch, gewünschtes Ergebnis, inneres Hindernis und Wenn-dann-Plan. Verwandte Forschung stützt Planung im Durchschnitt, bei unterschiedlichen Ergebnissen.",limitation:"Die Entwicklerseite ist keine unabhängige Prüfung. MCII-Befunde bestätigen nicht jede Variante der Methode und machen äußere Einschränkungen nicht zu einem Denkfehler."}],h=[{schemaVersion:2,revision:2,id:"turning-day-1",courseId:"turning-day",locale:"de",title:"Wieder auf Montag warten? Fang heute wirklich an",goal:"Mach einen hilfreichen kleinen Schritt für dein gewähltes Ziel. Plane dann die nächste Gelegenheit.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Was schiebst du immer auf nächsten Montag, obwohl du es heute ausprobieren könntest?",reason:{id:"turning-day-1-reason",label:"Was verdient zwei Minuten, und was kann warten?",kind:"text",maxLength:160,optional:!0,suggestions:["Platz für Kreativität schaffen","Üben, bevor noch eine Woche vergeht","Zeit für das schützen, was mir wichtig ist"]},why:{id:"turning-day-1-why",label:"Was verdient zwei Minuten, und was kann warten?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Datum kann beeinflussen, wann du anfangen willst. Ob du danach dranbleibst, ist damit nicht gesagt. In einem Experiment wählten mehr Menschen eine Erinnerung für dasselbe Märzdatum, wenn es als Frühlingsanfang beschrieben wurde. Die Studie zeigte nicht, ob sie die Erinnerung später auch nutzten.","Nutze die Gelegenheit für einen kleinen Schritt in deine gewählte Richtung. Zeichne einen Gegenstand, schreibe einen brauchbaren Satz oder lies einen benötigten Absatz. Ein Datum auszuwählen ist Vorbereitung. Mach den Schritt, halte ihn fest und wähle dein nächstes Startsignal. Diesen Versuch führst du durch den ganzen Kurs weiter."],example:{title:"Lenas erste Zeichnung",text:"Lena verschiebt das Zeichnen immer auf Montag. Am Mittwoch skizziert sie nach dem Tee am Küchentisch zwei Minuten lang ihre Tasse. Der Henkel wird schief. Sie hält eine Skizze fest und wählt den Tee morgen als nächstes Startsignal. Den Mittwoch zum Anfang zu erklären half ihr bei der Entscheidung. Besser zeichnen konnte sie dadurch nicht."}},move:{invitation:"Wähle Zeichnen, Schreiben oder Lesen, wenn es deiner gewählten Richtung dient.",instructions:["Prüfe vor dem Ausfüllen, ob das Beispiel zu deiner gewählten Richtung passt.","Probiere deinen Schritt aus und halte danach hier fest, was passiert ist."],prompts:[],suggestions:{action:["Einen Gegenstand aus dem Alltag zeichnen","Einen brauchbaren Satz schreiben","Einen benötigten Absatz lesen"],minimum:["Eine kleine Skizze fertig zeichnen","Einen hilfreichen Satz schreiben","Einen ganzen Absatz lesen"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Nach meiner nächsten Tasse Tee","Nach meiner nächsten Mahlzeit"],place:["An meinem Küchentisch","An meinem gewohnten Arbeitsplatz","An meinem gut zugänglichen Leseplatz"],minutes:[2,1,5],fallback:["Kleineren Gegenstand oder angepasste Hilfsmittel nutzen","Bei Schwierigkeiten mit Tippen einen Satz diktieren","Barrierefreien Text nutzen oder laut vorlesen"],observation:["Die Skizze, die ich fertig gezeichnet habe","Der brauchbare Satz, den ich geschrieben habe","Der Absatz, den ich gelesen habe"],bundles:[{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",cue:"Nach meiner nächsten Tasse Tee",place:"An meinem Küchentisch",fallback:"Kleineren Gegenstand oder angepasste Hilfsmittel nutzen",observation:"Die Skizze, die ich fertig gezeichnet habe",minutes:2},{action:"Einen brauchbaren Satz schreiben",minimum:"Einen hilfreichen Satz schreiben",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gewohnten Arbeitsplatz",fallback:"Bei Schwierigkeiten mit Tippen einen Satz diktieren",observation:"Der brauchbare Satz, den ich geschrieben habe",minutes:2},{action:"Einen benötigten Absatz lesen",minimum:"Einen ganzen Absatz lesen",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gut zugänglichen Leseplatz",fallback:"Barrierefreien Text nutzen oder laut vorlesen",observation:"Der Absatz, den ich gelesen habe",minutes:2}]},suggested:{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",minutes:2,cueHint:"Nach meiner nächsten Tasse Tee",placeHint:"An meinem Küchentisch",obstacleHint:"Meine Zeit oder verfügbaren Hilfsmittel ändern sich",fallbackHint:"Kleineren Gegenstand oder angepasste Hilfsmittel nutzen",observationHint:"Die Skizze, die ich fertig gezeichnet habe",requiresChoice:!0},accessibleAlternative:"Schreibe, diktiere oder nutze angepasste Hilfsmittel. Bitte bei deinem gewählten Schritt um Hilfe, wenn du sie brauchst.",stopRule:"Wähle eine sichere Aufgabe. Passe sie an oder pausiere, wenn Gesundheit, Betreuung oder Barrierefreiheit Vorrang haben."},result:{question:"Was ist bei deinem gewählten Minimum tatsächlich passiert?",observationPrompt:"Was hast du gemacht, und was stand dir im Weg?"},judgment:{primary:{id:"turning-day-1-decision",scenario:"Lena hat am Küchentisch Papier und zwei freie Minuten. Sie möchte zeichnen, wartet aber meistens auf Montag.",question:"Welcher Schritt passt zu dieser Situation?",options:[{id:"draw-now",text:"Jetzt die Tasse daneben skizzieren, die Skizze festhalten und eine passende Gelegenheit für morgen wählen.",feedback:"So nutzt Lena die freie Gelegenheit zum Zeichnen. Die Skizze darf unfertig wirken. Halte fest, was du abgeschlossen hast, und wähle das nächste Startsignal für denselben Versuch."},{id:"schedule-course",text:"In den zwei Minuten einen vollständigen Zeichenkurs für die nächste Woche in den Kalender eintragen.",feedback:"Ein Kurs könnte später helfen. Aber Lena hat bereits Zeit und Material für eine Skizze. Ein Termin ist ein Plan. Zeichnen setzt ihre gewählte Richtung heute in die Tat um."},{id:"choose-supplies",text:"Zeichenmaterial für Anfänger vergleichen und danach entscheiden, welcher Gegenstand sich am leichtesten zeichnen lässt.",feedback:"Passende Hilfsmittel zählen, wenn sie fehlen. Lena hat schon Papier und einen brauchbaren Gegenstand. Weiter auszuwählen verbraucht diese Gelegenheit, ohne dass sie das Zeichnen tatsächlich ausprobiert."}],bestOptionId:"draw-now"}},carry:{takeaway:"Ein Anfang wird greifbar, wenn du einen hilfreichen Schritt machst.",followUp:{questionId:"turning-day-1-return",question:"Hast du deinen kleinen Schritt gemacht, als dein gewähltes Startsignal kam?",observationPrompt:"Was hast du tatsächlich gemacht oder bemerkt?",adjustmentPrompt:"Was soll bei der nächsten Gelegenheit bleiben oder sich ändern?"}},goDeeper:{sections:[{heading:"Eine Erinnerung ist noch kein Versuch",paragraphs:["Dai, Milkman und Riis untersuchten 2014 den Effekt von Neuanfängen anhand von drei Archivdatensätzen [T01]. Um bestimmte markante Kalenderdaten nahmen Diätsuchen, Besuche im Hochschulsport und neue Selbstverpflichtungsverträge zu. Das sind unterschiedliche Maße für einen Beginn. Sie belegen weder, dass das Datum die Veränderung verursacht hat, noch dass die Menschen ihre Ziele weiterverfolgten.","In einem späteren Experiment wählten 165 Erwachsene online zwischen Terminen für eine Zielerinnerung [T02]. Den 20. März wählten 25,61%, wenn er als Frühlingsanfang beschrieben wurde. Bei der Beschreibung als dritter Donnerstag waren es 7,23%. Verglichen wurde die Auswahl einer Erinnerung. Wer danach tatsächlich handelte, wissen wir dadurch nicht.","Du kannst heute zu deinem Anfang erklären, wenn dir das hilft. Das ist eine freiwillige Anregung von ODA. Der Kurs behauptet nicht, dass ein beliebig gewähltes Anfangsdatum diese Befunde wiederholt. Deine Aufzeichnung beginnt mit dem, was du tatsächlich tust."]},{heading:"Mach aus der Gelegenheit einen konkreten Schritt",paragraphs:["Ein Wenn-dann-Plan verbindet eine erkennbare Situation mit einem vorher gewählten Schritt. Gollwitzer und Sheeran werteten 94 unabhängige Tests mit 8.461 Menschen aus [T03]. Solche Pläne verbesserten im Durchschnitt das Erreichen von Zielen. Aufgaben, Gruppen und Forschungsmethoden unterschieden sich. Deshalb sagt der Durchschnitt wenig über deinen persönlichen Verlauf aus. Diese kurze ODA-Lektion wurde in der Übersicht nicht geprüft.","Wähle für diesen Versuch einen kleinen Schritt, der deiner Richtung dient. „Nach dem Tee am Küchentisch einen Gegenstand skizzieren“ nennt Startsignal, Ort und Handlung. Papier hinzulegen ist Vorbereitung. Eine Skizze zu zeichnen ist Zeichenübung. Beides kann nützlich sein. Halte aber fest, was du tatsächlich gemacht hast.","Deine Richtung kann Betreuung, Erholung, Verbundenheit oder Lernen sein. Wenn du hier keinen sicheren Schritt machen kannst, wähle eine passende spätere Gelegenheit oder Unterstützung. Ein Name im Kalender beseitigt keine tatsächliche Einschränkung."]}],sourceIds:["T01","T02","T03"]}},{schemaVersion:2,revision:2,id:"turning-day-2",courseId:"turning-day",locale:"de",title:"Dein Plan landet auf dem Sofa? Bereite dich vor",goal:"Probiere bei deinem bisherigen Versuch aus, wie du mit einem wahrscheinlichen Hindernis umgehen kannst.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Wo könnte dein guter Plan heute Nachmittag an deinem echten Alltag scheitern?",reason:{id:"turning-day-2-reason",label:"Was stoppte deinen letzten Versuch, und was lässt sich ändern?",kind:"text",maxLength:160,optional:!0,suggestions:["Startsignal kam während der Arbeit","Nach der Schicht brauchte ich Erholung","Ein benötigtes Hilfsmittel war nicht verfügbar"]},why:{id:"turning-day-2-why",label:"Was stoppte deinen letzten Versuch, und was lässt sich ändern?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bleib bei deinem hilfreichen kleinen Schritt. Prüfe, was ihn verhindern könnte. Auf manche Gefühle kannst du reagieren. Fehlen Kinderbetreuung, Ausrüstung, ein sicherer Ort oder Kraft, brauchst du andere Lösungen. Ändere einen unmöglichen Plan. Nicht jedes Hindernis liegt in dir.","Entscheide, was du bei einem Hindernis oder einer Gelegenheit tun kannst: „Wenn ich meine Arbeitsjacke ausziehe, skizziere ich am Tisch einen Gegenstand.“ Studien stützen konkrete Pläne im Durchschnitt, bei unterschiedlichen Ergebnissen. Aufschreiben ist Vorbereitung. Probiere deinen Schritt aus. Halte dann fest, ob er möglich war und ob du ihn gemacht hast."],example:{title:"Lenas Startsignal nach Feierabend",text:"Lenas Schichten enden zu unterschiedlichen Zeiten. Deshalb passt 18 Uhr selten zum Zeichnen. Sie wählt das Ausziehen der Arbeitsjacke als Startsignal. Am Küchentisch skizziert sie ihre Schlüssel, bevor sie eine Serie einschaltet. Eine einfache Skizze wird fertig. Nach der nächsten Spätschicht braucht sie dagegen erst einmal Erholung und zeichnet nicht."}},move:{invitation:"Behalte deine gespeicherte Handlung und dein Minimum. Ändere ein beobachtetes Hindernis oder eine Gelegenheit.",instructions:["Behalte passende Startsignale. Ändere „Bei einem Hindernis“ für die Hürde aus deinem letzten Versuch.","Noch kein Versuch? Wähle eine passende Gelegenheit für denselben Schritt."],prompts:[],suggestions:{action:["Einen Gegenstand aus dem Alltag zeichnen","Einen brauchbaren Satz schreiben","Einen benötigten Absatz lesen"],minimum:["Eine kleine Skizze fertig zeichnen","Einen hilfreichen Satz schreiben","Einen ganzen Absatz lesen"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Nachdem ich meine Arbeitsjacke ausgezogen habe","Wenn meine geplante Pause beginnt","Nach meiner nächsten Mahlzeit"],place:["An meinem Küchentisch","An meinem gewohnten Arbeitsplatz","An meinem gut zugänglichen Leseplatz"],minutes:[2,1,5],fallback:["Ausruhen; morgen die Pause am Nachmittag nutzen","Ausruhen; morgen eine verfügbare Arbeitspause nutzen","Ausruhen; morgen nach der Mahlzeit lesen"],observation:["Ob das Startsignal kam und ich zeichnete","Ob das Startsignal kam und ich schrieb","Ob das Startsignal kam und ich las"],bundles:[{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",cue:"Nachdem ich meine Arbeitsjacke ausgezogen habe",place:"An meinem Küchentisch",fallback:"Ausruhen; morgen die Pause am Nachmittag nutzen",observation:"Ob das Startsignal kam und ich zeichnete",minutes:2},{action:"Einen brauchbaren Satz schreiben",minimum:"Einen hilfreichen Satz schreiben",cue:"Wenn meine geplante Pause beginnt",place:"An meinem gewohnten Arbeitsplatz",fallback:"Ausruhen; morgen eine verfügbare Arbeitspause nutzen",observation:"Ob das Startsignal kam und ich schrieb",minutes:2},{action:"Einen benötigten Absatz lesen",minimum:"Einen ganzen Absatz lesen",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gut zugänglichen Leseplatz",fallback:"Ausruhen; morgen nach der Mahlzeit lesen",observation:"Ob das Startsignal kam und ich las",minutes:2}]},suggested:{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",minutes:2,cueHint:"Nachdem ich meine Arbeitsjacke ausgezogen habe",placeHint:"An meinem Küchentisch",obstacleHint:"Ich brauche nach einer Schicht Erholung",fallbackHint:"Ausruhen; morgen die Pause am Nachmittag nutzen",observationHint:"Ob das Startsignal kam und ich zeichnete"},accessibleAlternative:"Schreibe, diktiere oder nutze angepasste Hilfsmittel. Bitte bei deinem gewählten Schritt um Hilfe, wenn du sie brauchst.",stopRule:"Mach bei Erschöpfung, Gefahr oder fehlendem Zugang nicht weiter. Wähle Erholung, Unterstützung oder eine andere Gelegenheit."},result:{question:"Was ist bei deinem gewählten Minimum tatsächlich passiert?",observationPrompt:"Was hast du gemacht, und was stand dir im Weg?"},judgment:{primary:{id:"turning-day-2-workday-cue-decision",scenario:"Lena möchte an normalen Arbeitstagen kurz zeichnen. Ihre Schichten wechseln, deshalb arbeitet sie um 18 Uhr oft noch. Die Jacke zieht sie zu Hause aus. Dort sind meistens zwei Minuten frei.",question:"Welcher Plan passt zu Arbeitstagen, ohne täglich neu zu planen?",options:[{id:"days-off-session",text:"Kurze Termine an freien Tagen wählen und auf einige Arbeitstage verzichten, um ihre Kraft zu schonen.",feedback:"Üben an freien Tagen kann Erholung schützen und zu einem anderen Ziel passen. Lena sucht kurze Gelegenheiten an Arbeitstagen. Das Heimkommen bietet sie, ohne jedes Schichtende vorhersagen zu müssen."},{id:"coat-cue",text:"Nach dem Ausziehen der Jacke einen Gegenstand skizzieren. Bei Erschöpfung Erholung oder eine andere passende Gelegenheit wählen.",feedback:"Das nutzt ein erkennbares Ereignis und lässt Erholung zu. Lena kann dieselbe kleine Zeichenübung testen. Weder die Uhr noch eine stärkere Erinnerung bestimmt, wann ihre Schicht endet."},{id:"shift-calendar-alert",text:"Täglich den Schichtplan prüfen und eine Erinnerung zum Zeichnen dreißig Minuten nach dem erwarteten Feierabend einstellen.",feedback:"Das kann funktionieren, wenn die Endzeiten stimmen. Wechselnde Schichten machen Erinnerungen aufwendig und unsicher. Das Heimkommen zeigt bereits einen verfügbaren Ort an. Teste dieses Startsignal und lass Erholung zu."}],bestOptionId:"coat-cue"}},carry:{takeaway:"Plane für deine tatsächlichen Bedingungen. Probiere den Schritt dann aus.",followUp:{questionId:"turning-day-2-return",question:"Kam dein Startsignal, und war dein geplanter Schritt tatsächlich möglich?",observationPrompt:"Was hast du tatsächlich gemacht oder bemerkt?",adjustmentPrompt:"Was soll bei der nächsten Gelegenheit bleiben oder sich ändern?"}},goDeeper:{sections:[{heading:"Nicht jedes Hindernis liegt in dir",paragraphs:["Beim mentalen Kontrastieren stellst du dem gewünschten Ergebnis das Hindernis gegenüber. Mit einem Wenn-dann-Plan zusammen heißt das oft MCII. Wang und Kollegen werteten 21 Artikel mit 24 unabhängigen Effekten und 15.907 Menschen aus [T04]. Sie fanden einen bescheidenen durchschnittlichen Nutzen für das Erreichen von Zielen. Die Studienergebnisse unterschieden sich, und eine Verzerrung durch bevorzugte Veröffentlichung bestimmter Ergebnisse war möglich.","Das Vorgehen kann zeigen, dass ein Wunsch angepasst werden muss. Es belegt nicht, dass Vorstellen Ergebnisse anzieht, jedes Hindernis ein Gefühl ist oder mehr Druck immer passt. Äußere Bedingungen gehören zur Prüfung: Ist der Schritt machbar? Geld, Barrierefreiheit, Arbeitslast und Betreuungspflichten sind mehr als fehlende Lust.","ODA regt an, deine gewählte Richtung beizubehalten und einen Schritt auszuprobieren. Das kann ein kleinerer Umfang, eine andere Gelegenheit oder eine konkrete Bitte sein. Halte zuerst fest, ob der Schritt möglich war. Erst dann kannst du beurteilen, ob er geholfen hat."]},{heading:"Geplante Stunden sind noch keine geleisteten Stunden",paragraphs:["In einer Studie zum Zeitmanagement wurden 84 deutsche Studierende zufällig drei Gruppen zugeteilt [T15]. Die Gruppe mit mentalem Kontrastieren und Planung plante mehr Stunden ein als die Kontrollgruppen. Der vorab geplante Vergleich war signifikant, der Gesamttest über alle Bedingungen lag bei p = 0,057. Gemessen wurden geplante Stunden. Wie viele Stunden die Teilnehmenden tatsächlich arbeiteten, zeigte die Studie nicht.","In einer breiteren Forschungsübersicht verbesserten konkrete Wenn-dann-Pläne im Durchschnitt das Erreichen von Zielen [T03]. Die Experimente prüften keine einheitliche Zeitdauer und keine allgemeingültige tägliche Dosis. ODAs kurzer Versuch und der Rückblick am nächsten Tag sind pädagogische Anpassungen. Sie entsprechen nicht dem ursprünglichen Forschungsablauf.","Eine hilfreiche Beobachtung trennt drei Fragen: Kam das Startsignal? War der geplante Schritt möglich? Hast du ihn gemacht? Trat das Hindernis nie auf, bleibt dein Ausweichschritt ungeprüft. War der Schritt unmöglich, ändere die Bedingungen oder den Plan."]}],sourceIds:["T03","T04","T15"]}},{schemaVersion:2,revision:2,id:"turning-day-3",courseId:"turning-day",locale:"de",title:"„Ich ziehe nie etwas durch“? Prüfe die Fakten",goal:"Mach bei deinem bisherigen Versuch einen hilfreichen kleinen Schritt. Beschreibe genau, was dieser Versuch belegt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Wurde aus einem holprigen Versuch schon wieder ein Urteil über dein ganzes Leben?",reason:{id:"turning-day-3-never-fact-check-reason",label:"Was an deinem „nie“ bestätigt oder widerlegt der letzte Versuch?",kind:"text",maxLength:160,optional:!0,suggestions:["Schritt gemacht; Können braucht noch Übung","Startsignal verpasst; Können bleibt ungeprüft","Noch keinen Versuch festgehalten"]},why:{id:"turning-day-3-why",label:"Wozu wäre eine ehrliche kleine Übung diese Woche gut?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Was du dir bei einer bestimmten Aufgabe zutraust, ist etwas anderes als dein Wert als Mensch. Eine Theorie schreibt eigenen Erfolgen eine wichtige Rolle für diese Erwartung zu. Sie beweist nicht, dass jede winzige Handlung Selbstvertrauen stärkt oder umfassendes Können zeigt.","Kehre zu deinem bisherigen kleinen Schritt zurück. Beschreibe ihn genau: „Ich habe einen Gegenstand gezeichnet. Die Umrisse brauchen Übung.“ Ein unvollkommener Versuch kann dein Minimum erfüllen und zugleich eine Wissenslücke zeigen. Zwei Minuten sind ein praktischer Anfangswert, keine erforschte optimale Dauer. Dein Selbstvertrauen darf unverändert bleiben. Halte den Schritt trotzdem fest."],example:{title:"Lenas schiefer Henkel",text:"Nach dem Ausziehen der Jacke skizziert Lena am Küchentisch eine Tasse. Der Henkel ist wieder schief. Sie fühlt sich nicht sicherer. Ihre Notiz lautet: „Eine Tasse gezeichnet. Die Proportionen des Henkels brauchen Übung.“ Für den nächsten freien Nachmittag wählt sie denselben Schritt. Eine Zeichnung beweist noch nicht, dass sie ein Plakat gestalten kann."}},move:{invitation:"Behalte Handlung und Startsignal. Halte fest, was entstanden ist und was noch offenbleibt.",instructions:["Behalte deine Handlung und dein Minimum.","Nenne unter „Worauf achtest du?“ dein Ergebnis und was noch nicht klappt."],prompts:[],suggestions:{action:["Einen Gegenstand aus dem Alltag zeichnen","Einen brauchbaren Satz schreiben","Einen benötigten Absatz lesen"],minimum:["Eine kleine Skizze fertig zeichnen","Einen hilfreichen Satz schreiben","Einen ganzen Absatz lesen"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Nach meiner nächsten Tasse Tee","In meiner nächsten verfügbaren Pause","Nach meiner nächsten Mahlzeit"],place:["An meinem Küchentisch","An meinem gewohnten Arbeitsplatz","An meinem gut zugänglichen Leseplatz"],minutes:[2,1,5],fallback:["Um Hilfe beim Zeichnen des Henkels bitten","Die noch zu prüfende Angabe markieren","Die noch unklare Stelle markieren"],observation:["Meine Skizze und ein Detail zum Üben","Mein Satz und eine noch ungeprüfte Angabe","Gelesener Absatz und eine noch unklare Stelle"],bundles:[{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",cue:"Nach meiner nächsten Tasse Tee",place:"An meinem Küchentisch",fallback:"Um Hilfe beim Zeichnen des Henkels bitten",observation:"Meine Skizze und ein Detail zum Üben",minutes:2},{action:"Einen brauchbaren Satz schreiben",minimum:"Einen hilfreichen Satz schreiben",cue:"In meiner nächsten verfügbaren Pause",place:"An meinem gewohnten Arbeitsplatz",fallback:"Die noch zu prüfende Angabe markieren",observation:"Mein Satz und eine noch ungeprüfte Angabe",minutes:2},{action:"Einen benötigten Absatz lesen",minimum:"Einen ganzen Absatz lesen",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gut zugänglichen Leseplatz",fallback:"Die noch unklare Stelle markieren",observation:"Gelesener Absatz und eine noch unklare Stelle",minutes:2}]},suggested:{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",minutes:2,cueHint:"Nach meiner nächsten Tasse Tee",placeHint:"An meinem Küchentisch",obstacleHint:"Bei einem Teil brauche ich noch Hilfe",fallbackHint:"Um Hilfe beim Zeichnen des Henkels bitten",observationHint:"Meine Skizze und ein Detail zum Üben"},accessibleAlternative:"Schreibe, diktiere oder nutze angepasste Hilfsmittel. Bitte bei deinem gewählten Schritt um Hilfe, wenn du sie brauchst.",stopRule:"Übe sicher und im Rahmen deiner Möglichkeiten. Ein schlechtes Ergebnis kann Unterstützung, Anpassung oder eine Pause nahelegen."},result:{question:"Was ist bei deinem gewählten Minimum tatsächlich passiert?",observationPrompt:"Was hast du gemacht, und was stand dir im Weg?"},judgment:{primary:{id:"turning-day-3-specific-record-decision",scenario:"Lena hat die versprochene Tassenskizze fertig gezeichnet. Der Henkel ist schief, und sie fühlt sich nicht sicherer. Sie überlegt, was sie festhalten soll.",question:"Welche Notiz hilft bei der nächsten Übung am besten?",options:[{id:"repeat-before-assessing",text:"Die fertige Skizze festhalten und dieselbe Tasse unverändert wiederholen, bevor sie entscheidet, welches Detail Übung braucht.",feedback:"Wiederholen kann helfen, wenn das Übungsziel noch unklar ist. Lena kann den schiefen Henkel bereits benennen. Halte dieses Detail jetzt fest. Dann kann sie beim nächsten Versuch genau daran üben."},{id:"specific-evidence",text:"Eine fertige Tassenskizze und den schiefen Henkel festhalten. Dann die nächste Gelegenheit zum Üben wählen.",feedback:"Das benennt den Schritt und seine Grenze. Lena hat ihr Skizzenminimum erfüllt. Sie hat weder umfassendes Können bewiesen noch mehr Selbstvertrauen gebraucht. Beim nächsten Versuch kann sie den Henkel üben."},{id:"cue-reliability-from-once",text:"Die fertige Skizze festhalten und das Startsignal nächste Woche beibehalten, weil es heute funktioniert hat.",feedback:"Ein vielversprechendes Startsignal weiter auszuprobieren ist sinnvoll. Ein einzelner abgeschlossener Versuch belegt noch keine verlässliche Routine. Halte den schiefen Henkel fest und teste das Startsignal unter den nächsten Bedingungen erneut."}],bestOptionId:"specific-evidence"}},carry:{takeaway:"Beschreibe deinen Schritt genau. Übe danach das Detail, das noch fehlt.",followUp:{questionId:"turning-day-3-return",question:"Was hat dein abgeschlossener Schritt gezeigt, und was braucht noch Übung?",observationPrompt:"Was hast du tatsächlich gemacht oder bemerkt?",adjustmentPrompt:"Was soll bei der nächsten Gelegenheit bleiben oder sich ändern?"}},goDeeper:{sections:[{heading:"Was du dir bei einer Aufgabe zutraust",paragraphs:["Bandura beschreibt Selbstwirksamkeit 1977 als Erwartung, eine bestimmte Handlung ausführen zu können [T09]. Eigene Erfolge, andere zu beobachten, Ermutigung und körperliche Zustände liefern dafür Informationen. Die Theorie betont das eigene Bewältigen. Sie ist keine Studie, die beweist, dass jeder kleine Schritt Selbstvertrauen schafft oder eigene Erfolge in jeder Situation wichtiger sind als andere Unterstützung.","Für diesen Kurs macht die Unterscheidung deine Notiz nützlich. Eine fertige Skizze zeigt, dass du diese Skizze unter diesen Bedingungen gezeichnet hast. Sie kann etwas über Hilfsmittel, Startsignal oder dein jetziges Können verraten. Sie misst nicht deinen Wert und beweist nicht, dass du jedes künftige Projekt abschließen kannst.","Zeigt die Arbeit fehlendes Wissen, kann der nächste Schritt eine Anleitung oder Hilfe sein. Ändern sich deine Möglichkeiten oder die Sicherheit, passe den Versuch an oder pausiere. Das ist eine gewöhnliche Übung für persönliche Entwicklung. Sie behandelt keine starke Angst und prüft nicht deinen Charakter."]},{heading:"Klein anfangen heißt nicht, schon fertig zu sein",paragraphs:["James Clears Zwei-Minuten-Regel ist ein Praxistipp. Sie ist kein kontrollierter Befund, dass zwei Minuten optimal sind [T17]. Ein kurzer Anfang kann eine Aufgabe zugänglicher machen. Einen Stift hinzulegen ist aber Vorbereitung. Einen Gegenstand zu zeichnen ist Zeichenübung. Wähle ein Minimum, das deiner Richtung dient. Halte Vorbereitung ehrlich als Vorbereitung fest, wenn sie gerade der passende Schritt ist.","In Harkins Übersicht über 138 randomisierte Studien verbesserte das Beobachten von Fortschritten im Durchschnitt das Erreichen von Zielen [T05]. Ziele und Methoden unterschieden sich. Schriftliches Festhalten hing in zusätzlichen Analysen mit größeren Effekten zusammen. Das bestätigt weder ODAs genaue Notizform noch verlangt es öffentliches Teilen.","Eine kurze Notiz kann Ergebnis und Grenze gemeinsam benennen: einen brauchbaren Satz geschrieben, aber eine Angabe muss noch geprüft werden. Übertreibe nicht, weil sich der Schritt gut anfühlte. Streiche ihn nicht, weil du enttäuscht warst. Wähle den nächsten Schritt anhand der vorhandenen Beobachtungen."]}],sourceIds:["T09","T05","T17"]}},{schemaVersion:2,revision:2,id:"turning-day-4",courseId:"turning-day",locale:"de",title:"Stift gesucht, Zeit weg? Leg ihn griffbereit",goal:"Probiere bei deinem bisherigen kleinen Schritt aus, ob eine Änderung am Arbeitsplatz beim Startsignal hilft.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"War das nötige Werkzeug versteckt, während die Ablenkung direkt vor dir lag?",reason:{id:"turning-day-4-reason",label:"Was kannst du leichter bereitlegen, ohne wichtige Zugänge zu verlieren?",kind:"text",maxLength:160,optional:!0,suggestions:["Hilfsmittel beim Startsignal griffbereit haben","Für wichtige Kontakte erreichbar bleiben","Meine Notiz für mich behalten"]},why:{id:"turning-day-4-why",label:"Was kannst du leichter bereitlegen, ohne wichtige Zugänge zu verlieren?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Startsignal umfasst auch den Ort und die Bedingungen, nicht nur eine Handy-Erinnerung. Forschung beschreibt, wie Handlungen durch Wiederholung in ähnlichen Situationen zunehmend vom Startsignal ausgelöst werden können. Ein benötigter Gegenstand an seinem Platz kann Vorbereitung erleichtern. Mühe spart er nicht vollständig. Dass du dich erinnerst, garantiert er auch nicht.","Schau auf deine letzte Notiz. War das Suchen nach Hilfsmitteln die Hürde? Lege sie beim Startsignal bereit und probiere dort deinen Schritt aus. Halte nötige Anrufe, Betreuungshinweise und barrierefreie Hilfsmittel verfügbar. Du darfst deine Notiz für dich behalten. Umstellen ist Vorbereitung. Den Schritt zu machen prüft, ob sie hilft."],example:{title:"Lena bleibt für Anrufe erreichbar",text:"Lenas letzte Zeichenzeit verging mit der Suche nach Papier. Sie legt einen Notizblock und einen Stift neben ihre Teetasse. Nach dem Tee skizziert sie den Löffel. Ihr Handy bleibt für Familienanrufe erreichbar. Die Skizze hält sie privat fest. Diesmal half die Vorbereitung. Bei der Schicht morgen braucht sie vielleicht ein anderes Startsignal."}},move:{invitation:"Behalte Handlung, Startsignal und Ort. Probiere eine Änderung beim Bereitlegen deiner Hilfsmittel aus.",instructions:["Nenne unter „Worauf achtest du?“ eine Änderung an Material oder Zugang.","Probiere mit dieser Vorbereitung dasselbe Minimum aus."],prompts:[],suggestions:{action:["Einen Gegenstand aus dem Alltag zeichnen","Einen brauchbaren Satz schreiben","Einen benötigten Absatz lesen"],minimum:["Eine kleine Skizze fertig zeichnen","Einen hilfreichen Satz schreiben","Einen ganzen Absatz lesen"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Nach meiner nächsten Tasse Tee","Wenn meine geplante Pause beginnt","Nach meiner nächsten Mahlzeit"],place:["An meinem Küchentisch","An meinem gewohnten Arbeitsplatz","An meinem gut zugänglichen Leseplatz"],minutes:[2,1,5],fallback:["Einen gut zugänglichen Ersatzstift nutzen","Mein barrierefreies Ersatzwerkzeug zum Schreiben nutzen","Eine barrierefreie Fassung des Textes öffnen"],observation:["Wo der Stift beim Zeichnen griffbereit lag","Welche Änderung am Dateizugang beim Schreiben half","Welche Änderung am Textzugang beim Lesen half"],bundles:[{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",cue:"Nach meiner nächsten Tasse Tee",place:"An meinem Küchentisch",fallback:"Einen gut zugänglichen Ersatzstift nutzen",observation:"Wo der Stift beim Zeichnen griffbereit lag",minutes:2},{action:"Einen brauchbaren Satz schreiben",minimum:"Einen hilfreichen Satz schreiben",cue:"Wenn meine geplante Pause beginnt",place:"An meinem gewohnten Arbeitsplatz",fallback:"Mein barrierefreies Ersatzwerkzeug zum Schreiben nutzen",observation:"Welche Änderung am Dateizugang beim Schreiben half",minutes:2},{action:"Einen benötigten Absatz lesen",minimum:"Einen ganzen Absatz lesen",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gut zugänglichen Leseplatz",fallback:"Eine barrierefreie Fassung des Textes öffnen",observation:"Welche Änderung am Textzugang beim Lesen half",minutes:2}]},suggested:{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",minutes:2,cueHint:"Nach meiner nächsten Tasse Tee",placeHint:"An meinem Küchentisch",obstacleHint:"Material ist schwer zu finden oder erreichen",fallbackHint:"Einen gut zugänglichen Ersatzstift nutzen",observationHint:"Wo der Stift beim Zeichnen griffbereit lag"},accessibleAlternative:"Schreibe, diktiere oder nutze angepasste Hilfsmittel. Bitte bei deinem gewählten Schritt um Hilfe, wenn du sie brauchst.",stopRule:"Halte beim Umstellen Notfallkontakte, Betreuungskontakte und Kommunikation über barrierefreie Hilfsmittel weiterhin erreichbar."},result:{question:"Was ist bei deinem gewählten Minimum tatsächlich passiert?",observationPrompt:"Was hast du umgestellt, und was hast du tatsächlich gemacht?"},judgment:{primary:{id:"turning-day-4-decision",scenario:"Lena verlor eine Zeichenzeit, weil sie Papier suchte. Für Familienanrufe muss ihr Handy erreichbar bleiben. Ihren Fortschritt möchte sie für sich behalten.",question:"Welcher Schritt passt zu dieser Situation?",options:[{id:"mute-nonessential-alerts",text:"Unwichtige Benachrichtigungen stummschalten, Familienanrufe zulassen und sich darauf verlassen, dass sie sich an den Papierplatz erinnert.",feedback:"Das erhält nötige Kontakte und kann Unterbrechungen verringern. Das beobachtete Materialproblem bleibt bestehen. Lege das Zeichenmaterial beim Tee bereit und probiere dann dieselbe kleine Skizze aus."},{id:"ready-tools",text:"Papier neben die Teetasse legen, Familienanrufe zulassen und eine Skizze ausprobieren, die sie für sich festhält.",feedback:"Das geht das beobachtete Vorbereitungsproblem an. Lena muss weder etwas teilen noch Kontakte abschneiden. Beim Zeichnen zeigt sich, ob das bereitliegende Material bei dieser Gelegenheit geholfen hat."},{id:"private-reminder-first",text:"Eine private Zeichenerinnerung nach dem Tee einstellen und das Papier an seinem bisherigen Aufbewahrungsort lassen.",feedback:"Eine Erinnerung kann helfen, das Startsignal zu bemerken. Lena bemerkt den Tee bereits, findet aber das Papier nicht. Teste zuerst den Materialplatz. Falls später das Bemerken schwierig wird, erwäge eine Erinnerung."}],bestOptionId:"ready-tools"}},carry:{takeaway:"Prüfe die Vorbereitung beim tatsächlichen Schritt. Schütze deine Privatsphäre und wichtige Zugänge.",followUp:{questionId:"turning-day-4-return",question:"Half die Änderung, dein Startsignal zu nutzen und den kleinen Schritt zu machen?",observationPrompt:"Welche Änderung half bei deiner gespeicherten Handlung, und welche nicht?",adjustmentPrompt:"Was soll bei der nächsten Gelegenheit bleiben oder sich ändern?"}},goDeeper:{sections:[{heading:"Die Umgebung hilft, aber macht die Arbeit nicht",paragraphs:["Wood und Rünger beschreiben, wie wiederholte Handlungen in wiederkehrenden Situationen zunehmend durch Startsignale ausgelöst werden können [T08]. Bewusste Ziele und Gewohnheiten können zusammenwirken. Das ist eine zusammenfassende Übersicht. Sie beweist nicht experimentell, dass ein bestimmter Gegenstandsplatz allen hilft. Sie belegt weder einen begrenzten Willenskraftakku noch, dass Vorbereitung Schwierigkeiten mit dem Planen und Handeln beseitigt.","Lally und Kollegen beobachteten alltägliche Gesundheitsverhaltensweisen über 84 Tage [T06]. Wiederholung unter gleichbleibenden Bedingungen ging mit zunehmender selbstberichteter Automatisierung einher. Eine zufällig zugeteilte Gruppe ohne Übung gab es nicht. Daraus ergibt sich weder ein garantierter Zeitplan noch der genaue Effekt eines Stifts neben einer Tasse.","ODA lädt dich ein, eine kleine Änderung in deiner Umgebung zu testen, weil die letzte Notiz ein Vorbereitungsproblem zeigte. Behalte Handlung, Startsignal und Minimum erkennbar bei. So kann die nächste Beobachtung eine konkrete Frage beantworten: Waren die nötigen Materialien da, und hast du sie genutzt?"]},{heading:"Privates Festhalten ist eine gleichwertige Möglichkeit",paragraphs:["Harkin und Kollegen werteten 138 randomisierte Studien zum Beobachten von Fortschritten aus [T05]. Solche Maßnahmen verbesserten im Durchschnitt das Erreichen von Zielen. Schriftliches Festhalten und Berichten hingen in zusätzlichen Analysen mit größeren Effekten zusammen. Diese Vergleiche beweisen nicht, dass ein Freund genügt, öffentliches Teilen nötig ist oder private Notizen die schlechtere Wahl sind.","Wenn du möchtest, kannst du mit einer unterstützenden Person darüber sprechen. Du wählst die Person, die Informationen und den Anlass. Eine sachliche private Notiz ist hier eine vollständige Möglichkeit. Du musst dein Ziel nicht offenlegen, Anerkennung suchen oder Druck von einer Person zulassen, bei der du dich nicht sicher fühlst.","Auch ein anderer Handyplatz muss nötige Kontakte und Barrierefreiheit erhalten. Gehe die beobachtete Hürde an: einen Gegenstand außer Reichweite, eine schwer auffindbare Datei oder eine unwichtige Benachrichtigung. Halte Vorbereitung als Vorbereitung fest. Schau danach, was bei demselben kleinen Schritt tatsächlich passiert ist."]}],sourceIds:["T08","T05","T06"]}},{schemaVersion:2,revision:2,id:"turning-day-5",courseId:"turning-day",locale:"de",title:"Heute gescheitert? Schau heute Abend auf die Fakten",goal:"Prüfe, was bei deinem Versuch wirklich passiert ist. Plane eine passende nächste Gelegenheit, ohne die Vergangenheit umzuschreiben.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du nennst heute einen Fehlschlag? Was steht tatsächlich in deiner Notiz?",reason:{id:"turning-day-5-reason",label:"Was zeigt deine Notiz: Was muss sich ändern?",kind:"text",maxLength:160,optional:!0,suggestions:["Vorbereitung und Übung getrennt festhalten","Aus einer verpassten Gelegenheit lernen","Morgen bleibt ein Plan für später"]},why:{id:"turning-day-5-why",label:"Was zeigt deine Notiz: Was muss sich ändern?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Was du heute gemacht hast, gehört in die Aufzeichnung. Was du morgen vorhast, gehört in den Plan. Forschung stützt das Prüfen von Fortschritten im Durchschnitt. Ein bereitliegendes Hilfsmittel belegt aber keine ausgeführte Übung. Behalte das Minimum deines Plans.","Benenne bei deinem letzten Versuch den Schritt oder die Lücke. Wähle dann eine nächste Gelegenheit. Eine Studie verband mehr Selbstvergebung mit weniger späterem Aufschieben vor Prüfungen. Sie zeigte weder Ursache und Wirkung noch den Nutzen eines freundlichen Satzes. Prüfe die Fakten, ohne Selbstvorwürfe oder erfundenen Erfolg. Macht dich spätes Nachdenken sorgenvoller, wähle einen früheren Zeitpunkt."],example:{title:"Lenas Papier lag bereit",text:"Lena legte Papier neben die Tasse, blieb aber länger bei der Arbeit. Der abendliche Tee fand statt. Gezeichnet hat sie nicht. Bevor sie abschaltet hält sie die Vorbereitung getrennt fest und wählt fürs Zeichnen „Noch nicht“. Die Skizze nach dem Tee morgen bleibt ein Plan. Der Rückblick ist kurz. Enttäuscht ist sie trotzdem."}},move:{invitation:"Schau auf deinen gespeicherten Versuch. Behalte die Handlung und ändere eine Bedingung, die deine Notiz zeigt.",instructions:["Halte zuerst fest, was tatsächlich passiert ist. Ändere danach den nächsten Termin.","Behalte Handlung und Minimum. Ändere nur die Bedingung, die nicht passte."],prompts:[],suggestions:{action:["Einen Gegenstand aus dem Alltag zeichnen","Einen brauchbaren Satz schreiben","Einen benötigten Absatz lesen"],minimum:["Eine kleine Skizze fertig zeichnen","Einen hilfreichen Satz schreiben","Einen ganzen Absatz lesen"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["In meiner nächsten früher gelegenen Teepause","In meiner nächsten früher gelegenen Arbeitspause","Nach meiner nächsten Mahlzeit"],place:["An meinem Küchentisch","An meinem gewohnten Arbeitsplatz","An meinem gut zugänglichen Leseplatz"],minutes:[2,1,5],fallback:["Ausruhen; morgen die frühere Teepause nutzen","Ausruhen; morgen die frühere Arbeitspause nutzen","Ausruhen; morgen nach der früheren Mahlzeit lesen"],observation:["Meine Skizze beim neu gewählten Startsignal","Mein Satz beim neu gewählten Startsignal","Was ich beim neuen Startsignal gelesen habe"],bundles:[{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",cue:"In meiner nächsten früher gelegenen Teepause",place:"An meinem Küchentisch",fallback:"Ausruhen; morgen die frühere Teepause nutzen",observation:"Meine Skizze beim neu gewählten Startsignal",minutes:2},{action:"Einen brauchbaren Satz schreiben",minimum:"Einen hilfreichen Satz schreiben",cue:"In meiner nächsten früher gelegenen Arbeitspause",place:"An meinem gewohnten Arbeitsplatz",fallback:"Ausruhen; morgen die frühere Arbeitspause nutzen",observation:"Mein Satz beim neu gewählten Startsignal",minutes:2},{action:"Einen benötigten Absatz lesen",minimum:"Einen ganzen Absatz lesen",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gut zugänglichen Leseplatz",fallback:"Ausruhen; morgen nach der früheren Mahlzeit lesen",observation:"Was ich beim neuen Startsignal gelesen habe",minutes:2}]},suggested:{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",minutes:2,cueHint:"In meiner nächsten früher gelegenen Teepause",placeHint:"An meinem Küchentisch",obstacleHint:"Nach spätem Feierabend fehlt mir die Kraft",fallbackHint:"Ausruhen; morgen die frühere Teepause nutzen",observationHint:"Meine Skizze beim neu gewählten Startsignal"},accessibleAlternative:"Schreibe, diktiere oder nutze angepasste Hilfsmittel. Bitte bei deinem gewählten Schritt um Hilfe, wenn du sie brauchst.",stopRule:"Hör auf, wenn der Rückblick Sorgen verstärkt oder dich wach hält. Wähle einen früheren Zeitpunkt oder Erholung."},result:{question:"Was ist bei deinem gewählten Minimum tatsächlich passiert?",observationPrompt:"Was hast du gemacht, und was stand dir im Weg?"},judgment:{primary:{id:"turning-day-5-decision",scenario:"Lena zeichnete nach spätem Feierabend ihre eine Skizze nicht. Papier hatte sie bereitgelegt. Morgen gibt es eine frühere Teepause. Eine längere Einheit am Wochenende wäre auch möglich.",question:"Welcher Schritt passt zu dieser Situation?",options:[{id:"same-cue-new-alert",text:"Beim Zeichnen „Noch nicht“ festhalten, das abendliche Startsignal beibehalten und für dieselbe Zeit eine Erinnerung hinzufügen.",feedback:"Das hält die Aufzeichnung ehrlich. Eine Erinnerung hilft beim Bemerken. Lenas Hürde war aber fehlende Kraft nach spätem Feierabend. In der früheren Teepause kann sie dasselbe Minimum unter passenderen Bedingungen testen."},{id:"honest-change",text:"Vorbereitung getrennt und Zeichnen als „Noch nicht“ festhalten. Für dasselbe Minimum ein früheres passendes Startsignal wählen.",feedback:"Das erhält das versprochene Minimum und beschreibt die Fakten. Morgen bleibt ein Plan. Lena kann das Startsignal ändern, ohne Vorbereitung als Zeichnen auszugeben oder den ganzen Tag zu verurteilen."},{id:"weekend-session",text:"Beim Zeichnen „Noch nicht“ festhalten und den Versuch auf eine längere Einheit am Wochenende verlegen.",feedback:"Das Wochenende ist eine berechtigte Wahl, wenn es besser passt. Hier gibt es morgen eine frühere Pause. Dasselbe Minimum dort zu testen verändert weniger, als Zeitpunkt und Umfang gleichzeitig zu ändern."}],bestOptionId:"honest-change"}},carry:{takeaway:"Halte die Vergangenheit ehrlich fest. Ändere die nächste Gelegenheit, wenn die Fakten dafür sprechen.",followUp:{questionId:"turning-day-5-return",question:"Passte die neue Gelegenheit besser, und was hast du tatsächlich gemacht?",observationPrompt:"Was hast du tatsächlich gemacht oder bemerkt?",adjustmentPrompt:"Was soll bei der nächsten Gelegenheit bleiben oder sich ändern?"}},goDeeper:{sections:[{heading:"Fair zurückblicken und Verantwortung behalten",paragraphs:["Wohl und Kollegen begleiteten 119 Studierende im ersten Studienjahr rund um zwei Zwischenprüfungen [T12]. Wer sich früheres Aufschieben eher vergab, schob vor der nächsten Prüfung weniger auf. Das war eine Beobachtungsstudie in einem Kurs. Sie belegt nicht, dass Vergebung die Veränderung verursachte, ein vorgegebener Satz Verhalten verändert oder Selbstkritik immer zu Vermeidung führt.","Du musst dir nicht schon vergeben haben, um die Fakten festzuhalten. „Ich habe Papier vorbereitet, aber wegen des späten Feierabends nicht gezeichnet“ nennt zwei getrennte Tatsachen. „Morgen zeichne ich nach meinem ersten Tee“ nennt einen Plan. Behalte diese Unterscheidung auch dann bei, wenn du vom ursprünglichen Versuch enttäuscht bist.","Das Beobachten von Fortschritten wird im Durchschnitt durch breitere experimentelle Befunde gestützt [T05]. ODAs genaue Zusammenfassung und Rückblick wurden dort aber nicht geprüft. Hier geht es um eine praktische Entscheidung: Wähle anhand vorhandener Informationen die nächste Bedingung. Gib dabei einen Plan nicht als Beleg aus."]},{heading:"Der Befund zur Liste vor dem Schlafen ist begrenzt",paragraphs:["Scullin und Kollegen untersuchten 57 gesunde Erwachsene zwischen 18 und 30 Jahren in einer Labornacht [T11]. Sie schrieben fünf Minuten mit Stift und Papier über künftige Aufgaben oder abgeschlossene Tätigkeiten. Die Gruppe mit künftigen Aufgaben schlief im Durchschnitt früher ein: nach 15,82 statt 25,09 Minuten. Verglichen wurde mit einer anderen Schreibaufgabe, nicht mit Nichtschreiben. Signifikant mehr Gesamtschlaf zeigte die Studie nicht.","Das Ergebnis bestätigt weder gesprochene Suggestionen noch das Vorstellen des nächsten Tages oder Erfolgsrückblicke als Schlafbehandlung. Die fünfminütige Papieraufgabe war ein eigener Ablauf. ODAs kurzer sachlicher Rückblick und Handlungsplan sind nicht diese geprüfte Maßnahme. Sie versprechen keinen Schlaf und verlangen kein Schreiben vor dem Zubettgehen.","Hör auf, wenn der Rückblick Sorgen verstärkt oder dich wach hält. Wähle eine frühere Gelegenheit. Erholung kann der passende nächste Schritt sein. Anhaltende Schlafprobleme sollten fachlich abgeklärt werden. Warte damit nicht auf das Kursende. Bleib bei deinem bisherigen kleinen Versuch. Ein neues Abendritual brauchst du dafür nicht."]}],sourceIds:["T05","T12","T11"]}},{schemaVersion:2,revision:2,id:"turning-day-6",courseId:"turning-day",locale:"de",title:"Tage ausgelassen? Plane eine Woche, die zu dir passt",goal:"Plane anhand deiner bisherigen Notizen eine realistische nächste Woche für denselben Versuch. Sichere Pausen gehören dazu.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Was zeigen deine Notizen über die Woche, die du tatsächlich hast?",reason:{id:"turning-day-6-reason",label:"Dient dir dieser Schritt, und ist sein Aufwand machbar?",kind:"text",maxLength:160,optional:!0,suggestions:["Den Teil behalten, der für mich passt","Startsignal ändern, statt Versäumtes nachzuholen","Platz für Erholung in meiner Woche schaffen"]},why:{id:"turning-day-6-why",label:"Dient dir dieser Schritt, und ist sein Aufwand machbar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Vergleiche für denselben Versuch geplante Gelegenheiten, tatsächliche Versuche und brauchbare Ergebnisse. Eine Woche prüft, ob der Plan passt. Sie macht noch keine fertige Gewohnheit. Die oft genannten 18 bis 254 Tage waren Modellschätzungen aus einer Studie, die Menschen nur 84 Tage lang beobachtete.","Behalte den Schritt bei, verkleinere ihn, ändere das Startsignal oder pausiere. Eine verpasste Gelegenheit störte den untersuchten Ablauf nicht wesentlich. Eine Grenze bei zwei ausgelassenen Gelegenheiten wurde nicht belegt. Speichere eine passende nächste Gelegenheit. ODA plant den Rückblick am nächsten Tag. Behalte den Verlauf mit seinen Lücken."],example:{title:"Lenas Woche hat Lücken",text:"Lena plante fünf Zeichenzeiten und zeichnete dreimal. Beide Lücken kamen nach Spätschichten. Beim Sonntagstee behält sie das Minimum von einem Gegenstand. Nur das Startsignal nach Spätschichten verschiebt sie auf die Nachmittagspause am Montag. Sie speichert die Gelegenheit. ODA plant den Rückblick für Dienstag. Drei einfache Skizzen bleiben drei Skizzen, mit zwei ehrlichen Lücken."}},move:{invitation:"Behalte deinen gespeicherten Schritt und passende Startsignale. Ändere nur die Bedingung, die dich aufgehalten hat.",instructions:["Noch keine Notiz? Wähle einen ersten machbaren Versuch.","Speichere die nächste Gelegenheit. ODA plant den Rückblick für den folgenden Tag."],prompts:[],suggestions:{action:["Einen Gegenstand aus dem Alltag zeichnen","Einen brauchbaren Satz schreiben","Einen benötigten Absatz lesen"],minimum:["Eine kleine Skizze fertig zeichnen","Einen hilfreichen Satz schreiben","Einen ganzen Absatz lesen"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["In meiner nächsten Teepause am Nachmittag","In meiner nächsten verfügbaren Arbeitspause","Nach meiner nächsten Mahlzeit"],place:["An meinem Küchentisch","An meinem gewohnten Arbeitsplatz","An meinem gut zugänglichen Leseplatz"],minutes:[2,1,5],fallback:["Ausruhen; die nächste Pause am Nachmittag nutzen","Die für morgen reservierte Arbeitspause nutzen","Nach der nächsten passenden Mahlzeit lesen"],observation:["Meine Skizze und ob das Startsignal passte","Mein Satz und ob das Startsignal passte","Gelesener Text und ob das Startsignal passte"],bundles:[{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",cue:"In meiner nächsten Teepause am Nachmittag",place:"An meinem Küchentisch",fallback:"Ausruhen; die nächste Pause am Nachmittag nutzen",observation:"Meine Skizze und ob das Startsignal passte",minutes:2},{action:"Einen brauchbaren Satz schreiben",minimum:"Einen hilfreichen Satz schreiben",cue:"In meiner nächsten verfügbaren Arbeitspause",place:"An meinem gewohnten Arbeitsplatz",fallback:"Die für morgen reservierte Arbeitspause nutzen",observation:"Mein Satz und ob das Startsignal passte",minutes:2},{action:"Einen benötigten Absatz lesen",minimum:"Einen ganzen Absatz lesen",cue:"Nach meiner nächsten Mahlzeit",place:"An meinem gut zugänglichen Leseplatz",fallback:"Nach der nächsten passenden Mahlzeit lesen",observation:"Gelesener Text und ob das Startsignal passte",minutes:2}]},suggested:{action:"Einen Gegenstand aus dem Alltag zeichnen",minimum:"Eine kleine Skizze fertig zeichnen",minutes:2,cueHint:"In meiner nächsten Teepause am Nachmittag",placeHint:"An meinem Küchentisch",obstacleHint:"Spätschichten verhindern das Üben zu dieser Zeit",fallbackHint:"Ausruhen; die nächste Pause am Nachmittag nutzen",observationHint:"Meine Skizze und ob das Startsignal passte"},accessibleAlternative:"Schreibe, diktiere oder nutze angepasste Hilfsmittel. Bitte bei deinem gewählten Schritt um Hilfe, wenn du sie brauchst.",stopRule:"Krankheit, Erschöpfung, Betreuung oder unsichere Bedingungen können mehrere Pausen hintereinander nötig machen. Beginne erst wieder, wenn es möglich ist."},result:{question:"Was ist bei deinem gewählten Minimum tatsächlich passiert?",observationPrompt:"Was hast du gemacht, und was stand dir im Weg?"},judgment:{primary:{id:"turning-day-6-observed-fit-decision",scenario:"Lena plante fünf Skizzen und zeichnete drei. Beide Lücken kamen nach Spätschichten. Das Minimum von einem Gegenstand passte bei anderen Gelegenheiten.",question:"Welcher Schritt passt zu dieser Situation?",options:[{id:"shrink-before-moving",text:"Das Startsignal nach Spätschichten behalten, jede Skizze auf einen Umriss verkleinern und die nächste Woche ehrlich vergleichen.",feedback:"Eine kleinere Skizze könnte helfen, wenn der Umfang die Hürde wäre. Ihr jetziges Minimum passte bei anderen Gelegenheiten. Teste zuerst ein besser verfügbares Startsignal, statt den passenden Umfang zu ändern."},{id:"adjust-week",text:"Das Minimum von einem Gegenstand behalten, das Startsignal nach Spätschichten ändern und alle fünf Gelegenheiten festgehalten lassen.",feedback:"Das reagiert auf das Muster und hält den Verlauf ehrlich. Lena kann ein anderes passendes Startsignal testen. Die drei Skizzen zählen als Ergebnisse. Eine fertige Gewohnheit belegen sie nicht."},{id:"compensate-output",text:"Das Startsignal nach Spätschichten behalten und an freien Tagen zusätzliche Gegenstände zeichnen, um die fehlenden Ergebnisse nachzuholen.",feedback:"Mehr Zeichnen kann ihrem Ziel dienen, wenn sie es möchte. Der bekannte Konflikt beim Startsignal bleibt aber bestehen. Verbessere zuerst die Gelegenheit nach Spätschichten, bevor du zusätzliche Arbeit zum Nachholen einplanst."}],bestOptionId:"adjust-week"}},carry:{takeaway:"Nutze deine Notizen für die nächste Woche. Erholung und sichere Pausen gehören dazu.",followUp:{questionId:"turning-day-6-return",question:"War die nächste Gelegenheit durch deine gewählte Änderung besser machbar?",observationPrompt:"Was hast du tatsächlich gemacht oder bemerkt?",adjustmentPrompt:"Was soll bei der nächsten Gelegenheit bleiben oder sich ändern?"}},goDeeper:{sections:[{heading:"Die Gewohnheitsdauer wurde im Modell geschätzt",paragraphs:["Lally und Kollegen beobachteten 96 Freiwillige über 84 Tage [T06]. 82 lieferten ausreichende Daten. Für 62 wurden Kurven angepasst, davon passten 39 gut. Bei diesen 39 Kurven lag die geschätzte Zeit bis zu 95% des geschätzten individuellen Endniveaus der Automatisierung zwischen 18 und 254 Tagen. Der Median war 66. Die 254 Tage waren eine Modellschätzung über den Beobachtungszeitraum hinaus, kein beobachteter Abschluss.","Die Studie nutzte Selbstauskünfte über alltägliche Gesundheitsverhaltensweisen und keine zufällig zugeteilte Kontrollgruppe. Eine verpasste Gelegenheit störte den untersuchten Ablauf nicht wesentlich. Das belegt keine Grenze, ab der zwei ausgelassene Gelegenheiten eine Gewohnheit zerstören. Mehrere Pausen hintereinander sind dadurch auch kein Charakterfehler.","Die Woche in diesem Kurs prüft die Machbarkeit. Dein Schritt für Zeichnen, Lernen, Betreuung oder Erholung kann von den untersuchten Handlungen abweichen. Prüfe anhand tatsächlicher Gelegenheiten und Ergebnisse, ob er passt. Eine Serie ohne Lücken ist kein geprüftes Maß für eine grundlegende Veränderung."]},{heading:"Führe deinen bisherigen Versuch sinnvoll weiter",paragraphs:["Eine Übersicht von 2024 umfasste 20 Studien zu Gesundheitsgewohnheiten mit 2.601 Menschen [T07]. Nur vier lieferten Schätzungen zur Entstehungsdauer. Elf hatten ein hohes Verzerrungsrisiko. Unterschiedliche Definitionen und Methoden begrenzen einen gemeinsamen Zeitplan. Veränderungen der Gewohnheitsstärke vor und nach einer Maßnahme belegen keinen kontrollierten Behandlungseffekt. Sie sagen nicht, wann deine Handlung automatisch wird.","Maßnahmen zum Beobachten von Fortschritten verbesserten im Durchschnitt das Erreichen von Zielen in 138 randomisierten Studien [T05]. Nutze hier vorhandene Notizen, statt ein weiteres Ritual hinzuzufügen. Zähle geplante Gelegenheiten, gemeldete Versuche und entstandene brauchbare Ergebnisse getrennt. Fehlt eine Rückmeldung, bleibt der Ausgang unbekannt, bis du ihn beschreibst.","Entscheide, ob der Versuch noch deiner Richtung dient. Wiederhole einen passenden Schritt, ändere ein beobachtetes Problem, hole Unterstützung, ruhe dich aus oder höre auf. Mit der nächsten Gelegenheit speicherst du den ODA-Rückblick am nächsten Tag. Ein Wochenvergleich bleibt freiwillig in deinem privaten Kalender. Hier wird kein zweiter Termin angelegt. Die Lektion abzuschließen ist etwas anderes, als den Plan auszuführen."]}],sourceIds:["T06","T07","T05"]}}],c=[{id:"1676475382103-54041209cf6c",alt:"Eine Frau schreibt neben einer Kaffeetasse in ein Notizbuch"},{id:"1740815897057-a93a8cf98a70",alt:"Eine Frau geht auf einem von Bäumen gesäumten Weg im Park"},{id:"1758854486305-eb7621f1e2e4",alt:"Eine Person arbeitet am Tisch neben einem großen Bogenfenster"},{id:"1756312177615-e153c9db507d",alt:"Eine Frau telefoniert in einer Küche"},{id:"1768219565623-501f93ae384b",alt:"Ein Schreibtisch im abendlichen Licht einer Lampe"},{id:"1529651737248-dad5e287768e",alt:"Ein Stift liegt auf einem Terminkalender"}],s=[0,1,1,1,1,1],u={id:"turning-day",title:"Wieder auf Montag warten? Fang heute wirklich an",subtitle:"Sechs Lektionen. Probiere eine hilfreiche Veränderung, erkenne Hindernisse und plane eine Woche, die zu dir passt.",description:"Mach einen hilfreichen Schritt in eine Richtung, die du selbst wählst. Führe denselben Versuch durch sechs Lektionen weiter: anfangen, mit einer Hürde umgehen, genau festhalten, die Vorbereitung testen, ehrlich zurückblicken und die nächste Woche passend planen.",scope:"Übungen für persönliche Entwicklung für Erwachsene. Sie sind keine Psychotherapie, Diagnose oder Behandlung. Sie versprechen keine Lebensveränderung an einem einzigen Tag. Setze Behandlungen oder Medikamente nicht ohne ärztliche Rücksprache ab. Wenn starke Angst, gedrückte Stimmung oder Belastung deinen Alltag erschweren, wende dich an eine medizinische oder psychotherapeutische Fachperson. Bei Gedanken, dir etwas anzutun, oder unmittelbarer Gefahr rufe die örtliche Notrufnummer an.",outcome:"Eine ausprobierte oder pausierte Veränderung, eine sachliche Aufzeichnung und ein machbarer nächster Termin.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Sonnenstrahlen fallen auf einen Weg zwischen Bäumen"},lang:"de",lessons:h.map((e,t)=>{const n=e.judgment.primary,r=n.options.find(i=>i.id===n.bestOptionId),a=n.options.filter(i=>i.id!==n.bestOptionId);return a.splice(s[t],0,r),{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,practice:[...e.move.instructions,"Komm hierher zurück und halte fest, was tatsächlich passiert ist."].slice(0,3),reflection:e.direction.reason.label,question:`${n.scenario} ${n.question}`,options:a.map(i=>i.text),correct:s[t],feedback:r.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:e.idea.example,photo:c[t]}})},d=Object.freeze(Object.defineProperty({__proto__:null,COURSE:u,LESSONS_V2:h,SOURCES:l},Symbol.toStringTag,{value:"Module"}));export{d as t};
